"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["8117"],{3122(e,n,t){t.r(n),t.d(n,{metadata:()=>a,default:()=>u,frontMatter:()=>i,contentTitle:()=>s,toc:()=>l,assets:()=>c});var a=JSON.parse('{"id":"reference/register/howtos/configurePrivateNetworks","title":"How to configure private networks for proper device operation","description":"almsc \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/register/howtos/configurePrivateNetworks.md","sourceDirName":"reference/register/howtos","slug":"/reference/register/howtos/configurePrivateNetworks","permalink":"/personal-av-docs/docs/reference/register/howtos/configurePrivateNetworks","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/register/howtos/configurePrivateNetworks.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to configure private networks for proper device operation","sidebar_label":"How to configure private networks for pr","sidebar_position":99,"edition":"almsc","source":"https://doc.airvantage.net/almsc/reference/register/howtos/configurePrivateNetworks","format":"md"}}'),o=t(4848),r=t(8453);let i={title:"How to configure private networks for proper device operation",sidebar_label:"How to configure private networks for pr",sidebar_position:99,edition:"almsc",source:"https://doc.airvantage.net/almsc/reference/register/howtos/configurePrivateNetworks",format:"md"},s,c={},l=[];function d(e){let n={a:"a",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(n.p,{children:[":::note Edition\n",(0,o.jsx)(n.strong,{children:"almsc"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,o.jsx)(n.a,{href:"https://doc.airvantage.net/almsc/reference/register/howtos/configurePrivateNetworks",children:"Original page"}),".\n:::"]}),"\n",(0,o.jsx)(n.p,{children:"How to configure private networks for proper device operation\nOverview of DNS and Firewall Considerations for AirVantage and ALMS\nAirLink routers and Semtech cellular modules require access to firmware updates and work best within a managed environment. AirVantage is the management platform for Semtech modules, and AirLink Management Service (ALMS) provides additional functionality for managing AirLink routers and Semtech cellular plans. If your firewall cannot be configured for DNS-based destinations, then the IP address used must be dynamically updated through ongoing DNS resolution.\nThe following are the requirements for firewall rules and required DNS entries to support these products in a safe and secure manner. These are relevant to private cellular networks, and also to router operation within a full tunnel VPN environment where management traffic is restricted.\nInitializing Table Of Contents...\nDNS Entries\nThe following DNS entries must be propagated to your internal DNS server(s) in order to support proper router behavior. The complete domains are required as most traffic is directed to specific subdomains, including for regional data center locations.\nairvantage.net\nm2mop.net\nFirewall Rules\nThe following ports must be allowed for outbound access (from your private network outbound to the domains listed and their corresponding responses) to the appropriate regional domains to support router communication and management, including firmware upgrades. All AirVantage and ALMS traffic should be configured by name for best results in the event of an address change.\nNote: In the case of routers that include out-of-band management (OOBM), only the Lightweight M2M (LwM2M) traffic is currently allowed through the OOBM link. Firmware downloads and log file uploads must be facilitated over a higher capacity WAN link, so firewall rules must be implemented on any private network link to support these services.\nDESTINATION PORT/PROTOCOL\nDESTINATION NAME\nFUNCTION\nNOTES\nUDP 5684/LwM2M\nbs.airvantage.net\nBootstrap\nNo device operational data is sent during bootstrap. All data is encrypted. One single global address.\nUDP 5684/LwM2M\nbsds.airvantage.net\nDual-stack bootstrap (see\nDual stack (IPv4 and IPv6) Support\nbelow)\nNo device operational data is sent during bootstrap. All data is encrypted. One single global address.\nUDP 5686/LwM2M\nlw.na.airvantage.net\nlw.eu.airvantage.net\nlw.cad.airvantage.net\nlw.au.airvantage.net\nDevice management communications\nAll data is encrypted. Traffic is sent only to the regional data center where your account is located.\nna\nis North America (USA)\neu\nis EMEA\ncad\nis Canada\nau\nis Australia\nUDP 5686/LwM2M\nlwds.na.airvantage.net\nlwds.eu.airvantage.net\nlwds.cad.airvantage.net\nlwds.au.airvantage.net\nDual-stack device management communications\nAll data is encrypted. Traffic is sent only to the regional data center where your account is located.\nna\nis North America (USA)\neu\nis EMEA\ncad\nis Canada\nau\nis Australia\nTCP 443/HTTPS\nna.airvantage.net\nna.m2mop.net\neu.airvantage.net\neu.m2mop.net\ncad.airvantage.net\nau.airvantage.net\nFirmware downloads and log file upload\nDownload is from digitally secured repository. Log files are sent over secured link. Some DNS entries are required for supporting legacy devices, and so are not needed for the newest AV/ALMS instances.\nTraffic is sent only to the regional data center where your account is located.\nna\nis North America (USA)\neu\nis EMEA\ncad\nis Canada\nau\nis Australia\nTCP 443/HTTPS\ndm.na.airvantage.net\ndm.eu.airvantage.net\ndm.cad.airvantage.net\ndm.au.airvantage.net\nDual-stack-enabled firmware downloads and log file upload\nDownload is from digitally secured repository. Log files are sent over secured link.\nTraffic is sent only to the regional data center where your account is located.\nna\nis North America (USA)\neu\nis EMEA\ncad\nis Canada\nau\nis Australia\nTCP 44900/M3DA\nna.airvantage.net\neu.airvantage.net\ncad.airvantage.net\nau.airvantage.net\nALEOS Application Framework (AAF) traffic\nOnly required by ALEOS router customers using M3DA/AAF, including ALEOS vehicle telemetry. Traffic is sent only to the regional data center where your account is located.\nna\nis North America (USA)\neu\nis EMEA\ncad\nis Canada\nau\nis Australia\nTCP 8883/MQTT over TLS\nna.airvantage.net\neu.airvantage.net\ncad.airvantage.net\nau.airvantage.net\nEncrypted MQTT traffic\nOnly required by ALEOS router customers who have AAF applications configured to report MQTT data to ALMS, including ALEOS vehicle telemetry. Unsecured MQTT (TCP/1883) should never be used. Traffic is sent only to the regional datacenter where your account is located.\nna\nis North America (USA)\neu\nis EMEA\ncad\nis Canada\nau\nis Australia\nDual stack (IPv4 and IPv6) Support\nAirVantage now supports both IPv4 and IPv6 connectivity, allowing you to connect and manage your AirLink routers, modules or other devices across different network configurations. IPv6 support includes bootstrap provisioning, device management communications (over LWM2M only), firmware downloads, and log file uploads.\nSupported Features\nWhen using the new endpoint, the following operations are supported on AirLink OS devices running\nAirLink OS 6.0 or later\n:\nDevice bootstrap and registration\nDevice management communications (over LWM2M only)\nFirmware over-the-air (FOTA) downloads\nDevice log file uploads\nDevice Compatibility\nIPv6 support is available on newer Semtech routers and modules that support dual-stack (IPv4/IPv6) networking. To verify whether your specific device model supports IPv6, please consult the documentation for your router or module product line.\nSupported AirLink Routers\nRX400 and EX400: AirLink OS 6.0 or later\nXR90, XR80, XR60 and RX55: AirLink OS 6.1 (release date TBA) or later\nConnectivity Options\nAirVantage supports the following connectivity scenarios.\nCONNECTIVITY SCENARIO\nNETWORK REQUIREMENT\nPLATFORM ENDPOINT\nCONFIGURATION REQUIRED\nIPv4-Only Networks (Legacy)\nIPv4 connectivity\nIPv4 bootstrap and device management\nNo change to the current network configuration, as described on this page\nIPv6/Dual-stack with DNS64/NAT64 Translation\nIPv4+IPv6 or IPv6 with DNS64/NAT64 translation enabled\nIPv4 bootstrap and device management (accessed via translation)\nConfigure your network for DNS64/NAT64.\nIPv6/Dual-Stack without Translation layer\nIPv4+IPv6 (dual-Stack) or IPv6 only Internet connectivity.\nNo (or dynamic) IP-based filtering on new AirVantage Endpoints DNS\nDual-Stack Device-Management Endpoints\nCompany must be enabled for IPv6 on platform (contact support).\nOptional: Manual device configuration to use dual-bootstrap endpoint url (IPv6-only scenario).\nDevices on an IPv6-only network without translation layer should not be rolled back without backup connectivity.\nEnabling IPv6 for Your Devices\nTo use native IPv6 connectivity:\nEnsure your device is an Airlink OS device with firmware versions above 6.0.0.\nContact Semtech support to request IPv6 enablement for the associated company.\nDeploy devices on your IPv6 or dual-stack network.\nOnce enabled, devices will automatically connect to the new device management endpoint after successful bootstrap.\nNetwork Configuration\nProper network configuration is essential for successful device connectivity to AirVantage. This includes DNS resolution and firewall rules to allow communication between your devices and the platform endpoints.\nFor detailed information on DNS configuration, firewall requirements, port configurations, and private network setup for both IPv4 and IPv6 connectivity, see\nFirewall Rules\nabove.\nBackward Compatibility\nAll existing IPv4 deployments continue to function without modification. Devices connecting to the original IPv4 bootstrap endpoint will continue using IPv4 for all platform communications, ensuring zero disruption to current operations.\nSupport\nFor assistance with IPv6 enablement or configuration questions, please contact Semtech support."})]})}function u(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},8453(e,n,t){t.d(n,{R:()=>i,x:()=>s});var a=t(6540);let o={},r=a.createContext(o);function i(e){let n=a.useContext(r);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),a.createElement(r.Provider,{value:n},e.children)}}}]);